INSERT INTO challenges (id, title, instructions, category, type, difficulty, concepts, spec, legacy)
VALUES
  ('inc-482', 'El botón Pagar no responde en el móvil y el menú tapa el formulario', 'No pasa nada al pulsar el botón. Esperado: Se envía el pago y aparece «Pago completado»', 'incidencias', 'incident', 'semi_senior', ARRAY['z-index', 'opacity vs visibility', 'selectores']::TEXT[], $webwiz_spec${"id":"inc-482","number":482,"type":"incident","title":"El botón Pagar no responde en el móvil y el menú tapa el formulario","area":"css","difficulty":"semi_senior","concepts":["z-index","opacity vs visibility","selectores"],"durationMin":10,"ticket":{"reporter":"Usuaria de la tienda","priority":"alta","device":"móvil, 390px","steps":["Abrir la tienda en el móvil","Abrir y cerrar el menú","Pulsar «Pagar 49,90 €»"],"expected":"Se envía el pago y aparece «Pago completado»","actual":"No pasa nada al pulsar el botón"},"viewport":390,"files":{"index.html":"<header class=\"topbar\">\n  <span class=\"logo\">Tienda Norte</span>\n  <button id=\"menu-toggle\" aria-expanded=\"false\" aria-controls=\"menu\">Menú</button>\n</header>\n<nav id=\"menu\" class=\"menu closed\">\n  <a href=\"#\">Ofertas</a>\n  <a href=\"#\">Pedidos</a>\n  <a href=\"#\">Ayuda</a>\n</nav>\n<main>\n  <h1>Pago</h1>\n  <form id=\"pago\">\n    <label for=\"tarjeta\">Tarjeta</label>\n    <input id=\"tarjeta\" value=\"4242 4242 4242 4242\">\n    <button type=\"button\" id=\"payBtn\">Pagar 49,90 €</button>\n  </form>\n  <p id=\"estado\" role=\"status\"></p>\n</main>","styles.css":"body { margin: 0; font-family: system-ui, sans-serif; }\n.topbar {\n  display: flex; justify-content: space-between; align-items: center;\n  height: 52px; padding: 0 16px; background: #161b22; color: white;\n}\n.menu {\n  position: fixed; top: 52px; left: 0; right: 0; bottom: 0; z-index: 1000;\n  display: flex; flex-direction: column; gap: 16px; padding: 24px;\n  background: rgba(13, 17, 23, 0.96); transition: opacity 0.2s;\n}\n.menu a { color: white; font-size: 1.25rem; }\n.menu.closed { opacity: 0; }\nmain { padding: 16px; }\n#payBtn { display: block; width: 100%; min-height: 48px; margin-top: 12px; }","app.js":"const toggle = document.getElementById(\"menu-toggle\");\nconst menu = document.getElementById(\"menu\");\n\ntoggle.addEventListener(\"click\", () => {\n  const abierto = !menu.classList.toggle(\"closed\");\n  toggle.setAttribute(\"aria-expanded\", String(abierto));\n});\n\nconst pagar = document.querySelector(\"#pay-btn\");\npagar.addEventListener(\"click\", async () => {\n  const estado = document.getElementById(\"estado\");\n  estado.textContent = \"Procesando…\";\n  const res = await fetch(\"/api/pay\", { method: \"POST\", body: JSON.stringify({ importe: 49.9 }) });\n  estado.textContent = res.ok ? \"Pago completado\" : \"No se pudo completar el pago\";\n});"},"editable":["styles.css","app.js"],"networkLog":[{"method":"POST","url":"/api/pay","status":200,"body":{"ok":true},"delayMs":60}],"tests":[{"name":"El botón Pagar recibe el toque (nada lo tapa)","type":"dom","code":"return hits('#payBtn') || 'Hay un elemento invisible encima del botón Pagar.';"},{"name":"Pagar envía la petición al servidor","type":"dom","code":"click('#payBtn'); await wait(120); return requests().some(r => r.method === 'POST' && r.url === '/api/pay') || 'Ninguna petición a /api/pay.';"},{"name":"Se confirma el pago a la usuaria","type":"dom","code":"await wait(100); return text('#estado') === 'Pago completado' || ('Estado: «' + text('#estado') + '»');"}],"regressionTests":[{"name":"El menú se abre y se cierra","type":"dom","code":"const hasta = async (ok) => { for (let i = 0; i < 30 && !ok(); i++) await wait(50); return ok(); }; click('#menu-toggle'); const abierto = $('#menu-toggle').getAttribute('aria-expanded') === 'true' && (await hasta(() => style('#menu', 'opacity') === '1')) && hits('#menu a'); click('#menu-toggle'); return abierto && $('#menu-toggle').getAttribute('aria-expanded') === 'false';"},{"name":"El menú conserva sus tres enlaces","type":"dom","code":"return $$('#menu a').length === 3;"},{"name":"La cabecera y el formulario siguen en su sitio","type":"dom","code":"return !!$('.topbar .logo') && !!$('#tarjeta') && rect('#payBtn').width > 300;"}],"hints":["Abre la consola: hay un error nada más cargar la página. Compara el selector con el id real del botón.","Con el menú «cerrado», inspecciona el elemento que hay encima del botón: opacity: 0 lo hace invisible, pero sigue recibiendo los toques."],"solution":{"styles.css":"body { margin: 0; font-family: system-ui, sans-serif; }\n.topbar {\n  display: flex; justify-content: space-between; align-items: center;\n  height: 52px; padding: 0 16px; background: #161b22; color: white;\n}\n.menu {\n  position: fixed; top: 52px; left: 0; right: 0; bottom: 0; z-index: 1000;\n  display: flex; flex-direction: column; gap: 16px; padding: 24px;\n  background: rgba(13, 17, 23, 0.96); transition: opacity 0.2s;\n}\n.menu a { color: white; font-size: 1.25rem; }\n.menu.closed { opacity: 0; visibility: hidden; }\nmain { padding: 16px; }\n#payBtn { display: block; width: 100%; min-height: 48px; margin-top: 12px; }","app.js":"const toggle = document.getElementById(\"menu-toggle\");\nconst menu = document.getElementById(\"menu\");\n\ntoggle.addEventListener(\"click\", () => {\n  const abierto = !menu.classList.toggle(\"closed\");\n  toggle.setAttribute(\"aria-expanded\", String(abierto));\n});\n\nconst pagar = document.querySelector(\"#payBtn\");\npagar.addEventListener(\"click\", async () => {\n  const estado = document.getElementById(\"estado\");\n  estado.textContent = \"Procesando…\";\n  const res = await fetch(\"/api/pay\", { method: \"POST\", body: JSON.stringify({ importe: 49.9 }) });\n  estado.textContent = res.ok ? \"Pago completado\" : \"No se pudo completar el pago\";\n});"},"rootCause":"Dos causas combinadas. En app.js, querySelector('#pay-btn') devuelve null porque el id real es payBtn: el listener nunca se registra y la consola muestra un TypeError. Además, en styles.css .menu.closed solo pone opacity: 0, así que el menú fijo con z-index: 1000 sigue encima del formulario capturando los toques aunque no se vea. El arreglo mínimo son 2 líneas: corregir el selector y añadir visibility: hidden (o pointer-events: none) a .menu.closed.","suspects":["opacity","visibility","pointer-events","z-index","position"]}$webwiz_spec$::jsonb, false),
  ('inc-317', 'La ficha de producto se sale de la pantalla en el móvil', 'Hay que desplazarse a la derecha y el botón queda cortado. Esperado: La ficha cabe en la pantalla, sin scroll lateral', 'incidencias', 'incident', 'junior', ARRAY['responsive', 'width vs max-width']::TEXT[], $webwiz_spec${"id":"inc-317","number":317,"type":"incident","title":"La ficha de producto se sale de la pantalla en el móvil","area":"css","difficulty":"junior","concepts":["responsive","width vs max-width"],"durationMin":5,"ticket":{"reporter":"Equipo de ventas","priority":"media","device":"móvil, 390px","steps":["Abrir la ficha de las zapatillas en un móvil","Intentar ver el botón completo"],"expected":"La ficha cabe en la pantalla, sin scroll lateral","actual":"Hay que desplazarse a la derecha y el botón queda cortado"},"viewport":390,"files":{"index.html":"<main class=\"tienda\">\n  <article class=\"producto\">\n    <div class=\"foto\" role=\"img\" aria-label=\"Zapatillas Trail X\"></div>\n    <h1>Zapatillas Trail X</h1>\n    <p class=\"precio\">89,90 €</p>\n    <button class=\"comprar\">Añadir al carrito</button>\n  </article>\n</main>","styles.css":"* { box-sizing: border-box; }\nbody { margin: 0; font-family: system-ui, sans-serif; background: #f6f8fa; }\n.tienda { padding: 16px; }\n.producto {\n  width: 420px;\n  padding: 20px;\n  background: white;\n  border: 1px solid #d0d7de;\n  border-radius: 16px;\n}\n.foto { height: 180px; border-radius: 12px; background: linear-gradient(135deg, #7aa2ff, #ffa657); }\n.precio { font-size: 1.5rem; font-weight: 700; }\n.comprar { width: 100%; min-height: 48px; border: 0; border-radius: 10px; background: #2f5bd3; color: white; font-size: 1rem; }","app.js":""},"editable":["styles.css"],"networkLog":[],"tests":[{"name":"Sin scroll horizontal en el móvil","type":"dom","code":"const d = document.documentElement; return d.scrollWidth <= d.clientWidth || ('La página mide ' + d.scrollWidth + 'px en una pantalla de ' + d.clientWidth + 'px.');"},{"name":"La ficha cabe y aprovecha el ancho","type":"dom","code":"const r = rect('.producto'), w = document.documentElement.clientWidth; return r.right <= w && r.width >= w - 34;"}],"regressionTests":[{"name":"El botón ocupa todo el ancho de la ficha","type":"dom","code":"return near(rect('.comprar').width, rect('.producto').width - 42, 2);"},{"name":"La foto mantiene su alto","type":"dom","code":"return near(rect('.foto').height, 180, 1);"},{"name":"La ficha conserva su padding","type":"dom","code":"return style('.producto', 'padding-left') === '20px';"}],"hints":["Un ancho fijo en píxeles no se adapta a pantallas más estrechas.","max-width limita el tamaño sin impedir que encoja: prueba width: 100% con max-width: 420px."],"solution":{"styles.css":"* { box-sizing: border-box; }\nbody { margin: 0; font-family: system-ui, sans-serif; background: #f6f8fa; }\n.tienda { padding: 16px; }\n.producto {\n  width: min(420px, 100%);\n  padding: 20px;\n  background: white;\n  border: 1px solid #d0d7de;\n  border-radius: 16px;\n}\n.foto { height: 180px; border-radius: 12px; background: linear-gradient(135deg, #7aa2ff, #ffa657); }\n.precio { font-size: 1.5rem; font-weight: 700; }\n.comprar { width: 100%; min-height: 48px; border: 0; border-radius: 10px; background: #2f5bd3; color: white; font-size: 1rem; }"},"rootCause":"La ficha tiene width: 420px fijo. En una pantalla de 390px (menos 32px de padding) no cabe, así que desborda y aparece scroll horizontal. Con width: min(420px, 100%) (o width: 100% y max-width: 420px) conserva su tamaño en escritorio y se adapta en móvil.","suspects":["width","max-width","box-sizing"]}$webwiz_spec$::jsonb, false),
  ('inc-205', 'El aviso de cookies queda detrás de la cabecera y no se puede aceptar', 'La cabecera tapa el botón aunque el aviso tiene z-index: 9999. Esperado: El aviso se ve completo y el botón se puede pulsar', 'incidencias', 'incident', 'senior', ARRAY['z-index', 'contexto de apilamiento']::TEXT[], $webwiz_spec${"id":"inc-205","number":205,"type":"incident","title":"El aviso de cookies queda detrás de la cabecera y no se puede aceptar","area":"css","difficulty":"senior","concepts":["z-index","contexto de apilamiento"],"durationMin":12,"ticket":{"reporter":"Lector del periódico","priority":"alta","device":"escritorio, 1280px","steps":["Entrar en la portada","Intentar pulsar «Aceptar» en el aviso de cookies"],"expected":"El aviso se ve completo y el botón se puede pulsar","actual":"La cabecera tapa el botón aunque el aviso tiene z-index: 9999"},"viewport":1280,"files":{"index.html":"<header class=\"cabecera\">Noticias Bilbao</header>\n<div class=\"contenido\">\n  <article>\n    <h1>Abre el nuevo puente sobre la ría</h1>\n    <p>Más de 3.000 personas cruzaron el puente durante la primera mañana…</p>\n  </article>\n  <div class=\"cookies\" role=\"dialog\" aria-labelledby=\"cookies-titulo\">\n    <h2 id=\"cookies-titulo\">Usamos cookies</h2>\n    <button id=\"aceptar\">Aceptar</button>\n  </div>\n</div>","styles.css":"body { margin: 0; font-family: system-ui, sans-serif; }\n.cabecera {\n  position: sticky; top: 0; z-index: 10; height: 72px;\n  display: flex; align-items: center; padding: 0 24px;\n  background: #161b22; color: white; font-weight: 700;\n}\n.contenido { position: relative; z-index: 1; padding: 24px; }\n.contenido article { height: 1500px; }\n.cookies {\n  position: fixed; top: 8px; right: 24px; z-index: 9999; width: 320px;\n  padding: 12px 16px; background: white; border: 1px solid #d0d7de; border-radius: 12px;\n}\n.cookies h2 { margin: 0 0 8px; font-size: 1rem; }\n#aceptar { min-height: 36px; padding: 0 16px; }","app.js":"document.getElementById(\"aceptar\").addEventListener(\"click\", () => {\n  document.querySelector(\".cookies\").hidden = true;\n});"},"editable":["styles.css"],"networkLog":[],"tests":[{"name":"El botón Aceptar recibe el clic","type":"dom","code":"return hits('#aceptar') || 'La cabecera está encima del botón Aceptar.';"},{"name":"El aviso queda por encima de la cabecera","type":"dom","code":"const c = rect('.cookies'); const el = document.elementFromPoint(c.left + 20, c.top + 10); return !!el && !!el.closest('.cookies');"}],"regressionTests":[{"name":"La cabecera sigue fija al hacer scroll","type":"dom","code":"window.scrollTo(0, 500); await wait(30); const top = rect('.cabecera').top; window.scrollTo(0, 0); return near(top, 0, 1);"},{"name":"La cabecera tapa el artículo al hacer scroll","type":"dom","code":"window.scrollTo(0, 300); await wait(30); const el = document.elementFromPoint(400, 36); window.scrollTo(0, 0); return !!el && !!el.closest('.cabecera');"},{"name":"«Aceptar» cierra el aviso","type":"dom","code":"click('#aceptar'); await wait(20); return $('.cookies').hidden === true;"}],"hints":["Un z-index solo compite con los elementos de su mismo contexto de apilamiento. ¿Qué padre crea uno?","position: relative + z-index: 1 en .contenido encierra al aviso en el nivel 1, por debajo de la cabecera (10)."],"solution":{"styles.css":"body { margin: 0; font-family: system-ui, sans-serif; }\n.cabecera {\n  position: sticky; top: 0; z-index: 10; height: 72px;\n  display: flex; align-items: center; padding: 0 24px;\n  background: #161b22; color: white; font-weight: 700;\n}\n.contenido { position: relative; padding: 24px; }\n.contenido article { height: 1500px; }\n.cookies {\n  position: fixed; top: 8px; right: 24px; z-index: 9999; width: 320px;\n  padding: 12px 16px; background: white; border: 1px solid #d0d7de; border-radius: 12px;\n}\n.cookies h2 { margin: 0 0 8px; font-size: 1rem; }\n#aceptar { min-height: 36px; padding: 0 16px; }"},"rootCause":".contenido tiene position: relative y z-index: 1, lo que crea un contexto de apilamiento. Todo lo que hay dentro (incluido el aviso con z-index: 9999) se apila como si fuera nivel 1, y la cabecera sticky (nivel 10) queda encima. Quitar el z-index de .contenido libera al aviso; subir el 9999 no sirve de nada.","suspects":["z-index","position","isolation","transform"]}$webwiz_spec$::jsonb, false),
  ('inc-128', 'La tercera métrica del panel aparece debajo en vez de al lado', '«Ingresos» salta a una segunda fila. Esperado: Las tres tarjetas en una fila, del mismo ancho', 'incidencias', 'incident', 'junior', ARRAY['box-sizing', 'flexbox']::TEXT[], $webwiz_spec${"id":"inc-128","number":128,"type":"incident","title":"La tercera métrica del panel aparece debajo en vez de al lado","area":"css","difficulty":"junior","concepts":["box-sizing","flexbox"],"durationMin":5,"ticket":{"reporter":"Responsable de producto","priority":"baja","device":"escritorio, 1280px","steps":["Abrir el panel de métricas"],"expected":"Las tres tarjetas en una fila, del mismo ancho","actual":"«Ingresos» salta a una segunda fila"},"viewport":1280,"files":{"index.html":"<section class=\"metricas\">\n  <div class=\"metrica\">Usuarios <strong>1.204</strong></div>\n  <div class=\"metrica\">Retos superados <strong>8.391</strong></div>\n  <div class=\"metrica\">Ingresos <strong>12.480 €</strong></div>\n</section>","styles.css":"body { margin: 0; padding: 24px; font-family: system-ui, sans-serif; }\n.metricas { display: flex; flex-wrap: wrap; }\n.metrica {\n  width: 33.333%;\n  padding: 24px;\n  border: 1px solid #d0d7de;\n  border-radius: 12px;\n}\n.metrica strong { display: block; font-size: 2rem; }","app.js":""},"editable":["styles.css"],"networkLog":[],"tests":[{"name":"Las tres métricas en una fila","type":"dom","code":"const t = $$('.metrica').map(m => Math.round(m.getBoundingClientRect().top)); return t.every(x => x === t[0]);"},{"name":"Ninguna se sale del panel","type":"dom","code":"const p = rect('.metricas'); return $$('.metrica').every(m => m.getBoundingClientRect().right <= p.right + 1);"}],"regressionTests":[{"name":"Las tres miden lo mismo","type":"dom","code":"const w = $$('.metrica').map(m => m.getBoundingClientRect().width); return w.every(x => near(x, w[0], 1));"},{"name":"Conservan el padding de 24px","type":"dom","code":"return style('.metrica', 'padding-left') === '24px';"},{"name":"Ocupan todo el ancho del panel","type":"dom","code":"const p = rect('.metricas'); const total = $$('.metrica').reduce((s, m) => s + m.getBoundingClientRect().width, 0); return total >= p.width - 2;"}],"hints":["Inspecciona una tarjeta: ¿su ancho real coincide con el 33,333% del panel?","Por defecto el padding y el borde se suman al width (content-box)."],"solution":{"styles.css":"body { margin: 0; padding: 24px; font-family: system-ui, sans-serif; }\n.metricas { display: flex; flex-wrap: wrap; }\n.metrica {\n  box-sizing: border-box;\n  width: 33.333%;\n  padding: 24px;\n  border: 1px solid #d0d7de;\n  border-radius: 12px;\n}\n.metrica strong { display: block; font-size: 2rem; }"},"rootCause":"Con el box-sizing por defecto (content-box), cada tarjeta mide 33,333% más 48px de padding y 2px de borde. Las tres juntas superan el 100% del panel y, con flex-wrap: wrap, la tercera baja de fila. box-sizing: border-box hace que el width incluya padding y borde.","suspects":["box-sizing","width","padding","flex-wrap"]}$webwiz_spec$::jsonb, false),
  ('inc-611', 'El buscador muestra resultados de una búsqueda anterior', 'Al cabo de un momento aparecen los resultados de «ja» (Jamón, Japón…). Esperado: Se ven los cursos que coinciden con «java»', 'incidencias', 'incident', 'senior', ARRAY['async/await', 'condiciones de carrera', 'AbortController']::TEXT[], $webwiz_spec${"id":"inc-611","number":611,"type":"incident","title":"El buscador muestra resultados de una búsqueda anterior","area":"javascript","difficulty":"senior","concepts":["async/await","condiciones de carrera","AbortController"],"durationMin":12,"ticket":{"reporter":"Alumno de la academia","priority":"media","device":"escritorio, 1280px","steps":["Escribir «ja» en el buscador","Seguir escribiendo hasta «java» rápidamente"],"expected":"Se ven los cursos que coinciden con «java»","actual":"Al cabo de un momento aparecen los resultados de «ja» (Jamón, Japón…)"},"viewport":1280,"files":{"index.html":"<main>\n  <label for=\"q\">Buscar cursos</label>\n  <input id=\"q\" type=\"search\" autocomplete=\"off\">\n  <ul id=\"resultados\" aria-live=\"polite\"></ul>\n</main>","styles.css":"body { margin: 0; padding: 24px; font-family: system-ui, sans-serif; }\n#q { display: block; width: 100%; max-width: 420px; min-height: 40px; margin-top: 6px; }\n#resultados { padding-left: 18px; }","app.js":"const q = document.getElementById(\"q\");\nconst resultados = document.getElementById(\"resultados\");\n\nfunction pintar(lista) {\n  resultados.replaceChildren(...lista.map((nombre) => {\n    const li = document.createElement(\"li\");\n    li.textContent = nombre;\n    return li;\n  }));\n}\n\nq.addEventListener(\"input\", async () => {\n  const termino = q.value.trim();\n  if (!termino) return pintar([]);\n  const res = await fetch(\"/api/buscar?q=\" + encodeURIComponent(termino));\n  const datos = await res.json();\n  pintar(datos.resultados);\n});"},"editable":["app.js"],"networkLog":[{"method":"GET","url":"/api/buscar?q=ja","status":200,"body":{"resultados":["Jamón ibérico","JavaScript","Japonés básico"]},"delayMs":320},{"method":"GET","url":"/api/buscar?q=java","status":200,"body":{"resultados":["Java","JavaScript"]},"delayMs":60}],"tests":[{"name":"Se muestran los resultados de la última búsqueda","type":"dom","code":"type('#q', 'ja'); await wait(10); type('#q', 'java'); await wait(480); const t = $$('#resultados li').map(li => li.textContent); return (t.join('|') === 'Java|JavaScript') || ('La lista muestra: ' + (t.join(', ') || 'nada'));"},{"name":"Una respuesta lenta no pisa a la más reciente","type":"dom","code":"type('#q', ''); await wait(20); type('#q', 'ja'); await wait(5); type('#q', 'java'); await wait(150); const pronto = $$('#resultados li').map(li => li.textContent).join('|'); await wait(330); const despues = $$('#resultados li').map(li => li.textContent).join('|'); return pronto === 'Java|JavaScript' && despues === 'Java|JavaScript';"}],"regressionTests":[{"name":"Una búsqueda simple sigue funcionando","type":"dom","code":"type('#q', 'java'); await wait(150); return $$('#resultados li').length === 2;"},{"name":"Borrar el texto vacía la lista","type":"dom","code":"type('#q', ''); await wait(30); return $$('#resultados li').length === 0;"},{"name":"Se consulta al servidor con el término escrito","type":"dom","code":"return requests().some(r => r.url === '/api/buscar?q=java');"}],"hints":["Abre la pestaña Red: la petición de «ja» tarda mucho más que la de «java» y termina después.","Descarta respuestas antiguas: guarda un contador de la última búsqueda o cancela la anterior con AbortController."],"solution":{"app.js":"const q = document.getElementById(\"q\");\nconst resultados = document.getElementById(\"resultados\");\n\nfunction pintar(lista) {\n  resultados.replaceChildren(...lista.map((nombre) => {\n    const li = document.createElement(\"li\");\n    li.textContent = nombre;\n    return li;\n  }));\n}\n\nlet ultima = 0;\nq.addEventListener(\"input\", async () => {\n  const id = ++ultima;\n  const termino = q.value.trim();\n  if (!termino) return pintar([]);\n  const res = await fetch(\"/api/buscar?q=\" + encodeURIComponent(termino));\n  const datos = await res.json();\n  if (id !== ultima) return;\n  pintar(datos.resultados);\n});"},"rootCause":"Cada pulsación lanza una petición, pero las respuestas no llegan en orden: la de «ja» tarda 320 ms y la de «java» 60 ms. Cuando por fin llega la de «ja», pinta encima de la buena. Hay que ignorar respuestas que no correspondan a la última búsqueda (contador o comparar el término) o cancelar la anterior con AbortController.","suspects":[]}$webwiz_spec$::jsonb, false),
  ('inc-702', 'Cada clic en «Añadir» suma dos unidades al carrito', 'Unidades: 2. Esperado: Unidades: 1', 'incidencias', 'incident', 'junior', ARRAY['addEventListener', 'ciclo de carga del DOM']::TEXT[], $webwiz_spec${"id":"inc-702","number":702,"type":"incident","title":"Cada clic en «Añadir» suma dos unidades al carrito","area":"javascript","difficulty":"junior","concepts":["addEventListener","ciclo de carga del DOM"],"durationMin":6,"ticket":{"reporter":"Atención al cliente","priority":"alta","device":"todos","steps":["Abrir el carrito","Pulsar una vez «Añadir una unidad»"],"expected":"Unidades: 1","actual":"Unidades: 2"},"viewport":768,"files":{"index.html":"<main class=\"carrito\">\n  <h1>Carrito</h1>\n  <p>Unidades: <output id=\"total\">0</output></p>\n  <button id=\"sumar\">Añadir una unidad</button>\n  <button id=\"vaciar\">Vaciar</button>\n</main>","styles.css":"body { margin: 0; padding: 24px; font-family: system-ui, sans-serif; }\nbutton { min-height: 40px; margin-right: 8px; }\n#total { font-weight: 700; }","app.js":"let total = 0;\nconst salida = document.getElementById(\"total\");\n\nfunction pintar() {\n  salida.textContent = String(total);\n}\n\nfunction iniciar() {\n  document.getElementById(\"sumar\").addEventListener(\"click\", () => {\n    total += 1;\n    pintar();\n  });\n  document.getElementById(\"vaciar\").addEventListener(\"click\", () => {\n    total = 0;\n    pintar();\n  });\n  pintar();\n}\n\niniciar();\ndocument.addEventListener(\"DOMContentLoaded\", iniciar);"},"editable":["app.js"],"networkLog":[],"tests":[{"name":"Un clic suma exactamente una unidad","type":"dom","code":"click('#vaciar'); click('#sumar'); return text('#total') === '1' || ('Unidades: ' + text('#total'));"},{"name":"Tres clics suman tres unidades","type":"dom","code":"click('#vaciar'); click('#sumar'); click('#sumar'); click('#sumar'); return text('#total') === '3' || ('Unidades: ' + text('#total'));"}],"regressionTests":[{"name":"El carrito empieza en 0","type":"dom","code":"return text('#total') === '0';"},{"name":"«Vaciar» deja el carrito a 0","type":"dom","code":"click('#sumar'); click('#vaciar'); return text('#total') === '0';"},{"name":"Siguen existiendo los dos botones","type":"dom","code":"return !!$('#sumar') && !!$('#vaciar');"}],"hints":["Pon un console.log dentro de iniciar(): ¿cuántas veces aparece?","El script ya se ejecuta con el DOM listo; la llamada extra desde DOMContentLoaded registra los listeners por segunda vez."],"solution":{"app.js":"let total = 0;\nconst salida = document.getElementById(\"total\");\n\nfunction pintar() {\n  salida.textContent = String(total);\n}\n\nfunction iniciar() {\n  document.getElementById(\"sumar\").addEventListener(\"click\", () => {\n    total += 1;\n    pintar();\n  });\n  document.getElementById(\"vaciar\").addEventListener(\"click\", () => {\n    total = 0;\n    pintar();\n  });\n  pintar();\n}\n\niniciar();"},"rootCause":"iniciar() se ejecuta dos veces: una directamente (el script va al final del body, el DOM ya existe) y otra en DOMContentLoaded. Cada ejecución añade un listener más al botón, así que un clic suma dos veces. Basta con inicializar una sola vez.","suspects":[]}$webwiz_spec$::jsonb, false),
  ('inc-415', 'La newsletter confirma la suscripción aunque el servidor la rechaza', 'Aparece «¡Suscripción confirmada!» y el usuario no recibe nada. Esperado: Aparece el motivo del rechazo: «El email ya está suscrito»', 'incidencias', 'incident', 'semi_senior', ARRAY['fetch', 'res.ok', 'manejo de errores']::TEXT[], $webwiz_spec${"id":"inc-415","number":415,"type":"incident","title":"La newsletter confirma la suscripción aunque el servidor la rechaza","area":"javascript","difficulty":"semi_senior","concepts":["fetch","res.ok","manejo de errores"],"durationMin":8,"ticket":{"reporter":"Equipo de marketing","priority":"media","device":"todos","steps":["Introducir un email ya suscrito","Pulsar «Suscribirme»"],"expected":"Aparece el motivo del rechazo: «El email ya está suscrito»","actual":"Aparece «¡Suscripción confirmada!» y el usuario no recibe nada"},"viewport":768,"files":{"index.html":"<main>\n  <h1>Newsletter</h1>\n  <form id=\"alta\">\n    <label for=\"email\">Email</label>\n    <input id=\"email\" type=\"email\" value=\"ana@ejemplo.com\" required>\n    <button>Suscribirme</button>\n  </form>\n  <p id=\"mensaje\" role=\"status\"></p>\n</main>","styles.css":"body { margin: 0; padding: 24px; font-family: system-ui, sans-serif; }\n#email { display: block; min-height: 40px; margin: 6px 0 12px; width: 100%; max-width: 360px; }\nbutton { min-height: 40px; }","app.js":"const form = document.getElementById(\"alta\");\nconst mensaje = document.getElementById(\"mensaje\");\n\nform.addEventListener(\"submit\", (e) => {\n  e.preventDefault();\n  const email = document.getElementById(\"email\").value;\n  fetch(\"/api/suscribir\", { method: \"POST\", body: JSON.stringify({ email }) });\n  mensaje.textContent = \"¡Suscripción confirmada!\";\n});"},"editable":["app.js"],"networkLog":[{"method":"POST","url":"/api/suscribir","status":422,"body":{"error":"El email ya está suscrito"},"delayMs":80}],"tests":[{"name":"No se confirma una suscripción rechazada","type":"dom","code":"$('#alta').requestSubmit(); await wait(200); return !/confirmada/i.test(text('#mensaje')) || 'Se muestra «confirmada» con un 422 del servidor.';"},{"name":"Se muestra el motivo que envía el servidor","type":"dom","code":"return text('#mensaje').includes('El email ya está suscrito') || ('Mensaje: «' + text('#mensaje') + '»');"}],"regressionTests":[{"name":"Se envía el email al servidor","type":"dom","code":"$('#alta').requestSubmit(); await wait(150); return requests().some(r => r.method === 'POST' && r.url === '/api/suscribir' && (r.body || '').includes('ana@ejemplo.com'));"},{"name":"El formulario no recarga la página","type":"dom","code":"return !!$('#alta') && !!$('#mensaje');"}],"hints":["En la pestaña Red la petición responde 422, pero el mensaje se escribe antes de que llegue la respuesta.","Espera la respuesta con await y comprueba res.ok; si no es correcta, lee el JSON y muestra su campo error."],"solution":{"app.js":"const form = document.getElementById(\"alta\");\nconst mensaje = document.getElementById(\"mensaje\");\n\nform.addEventListener(\"submit\", async (e) => {\n  e.preventDefault();\n  const email = document.getElementById(\"email\").value;\n  const res = await fetch(\"/api/suscribir\", { method: \"POST\", body: JSON.stringify({ email }) });\n  const datos = await res.json();\n  mensaje.textContent = res.ok ? \"¡Suscripción confirmada!\" : datos.error;\n});"},"rootCause":"El código no espera a la respuesta de fetch: escribe «confirmada» justo después de lanzar la petición. Además fetch solo rechaza con errores de red; un 422 resuelve normalmente, así que hay que esperar con await y comprobar res.ok antes de dar el alta por buena.","suspects":[]}$webwiz_spec$::jsonb, false),
  ('inc-233', 'El menú de usuario no se puede abrir con teclado ni lector de pantalla', 'El foco se salta «Mi cuenta» y el lector no lo anuncia. Esperado: El menú se anuncia como botón, se abre y se anuncia «expandido»', 'incidencias', 'incident', 'semi_senior', ARRAY['semántica', 'aria-expanded', 'foco']::TEXT[], $webwiz_spec${"id":"inc-233","number":233,"type":"incident","title":"El menú de usuario no se puede abrir con teclado ni lector de pantalla","area":"accesibilidad","difficulty":"semi_senior","concepts":["semántica","aria-expanded","foco"],"durationMin":8,"ticket":{"reporter":"Usuario de lector de pantalla","priority":"alta","device":"escritorio + NVDA","steps":["Navegar con Tab hasta «Mi cuenta»","Pulsar Enter"],"expected":"El menú se anuncia como botón, se abre y se anuncia «expandido»","actual":"El foco se salta «Mi cuenta» y el lector no lo anuncia"},"viewport":768,"files":{"index.html":"<header class=\"barra\">\n  <span>Panel</span>\n  <div class=\"cuenta\" id=\"cuenta-btn\">Mi cuenta ▾</div>\n  <ul id=\"cuenta-menu\" class=\"cuenta-menu\" hidden>\n    <li><a href=\"#\">Perfil</a></li>\n    <li><a href=\"#\">Facturación</a></li>\n    <li><a href=\"#\">Cerrar sesión</a></li>\n  </ul>\n</header>","styles.css":"body { margin: 0; font-family: system-ui, sans-serif; }\n.barra { position: relative; display: flex; justify-content: space-between; align-items: center; padding: 12px 24px; background: #161b22; color: white; }\n.cuenta { padding: 8px 12px; border-radius: 8px; background: #30363d; color: white; cursor: pointer; font: inherit; border: 0; }\n.cuenta-menu { position: absolute; right: 24px; top: 56px; margin: 0; padding: 8px; list-style: none; background: white; border: 1px solid #d0d7de; border-radius: 8px; }\n.cuenta-menu a { display: block; padding: 6px 12px; color: #1f2328; }","app.js":"const boton = document.getElementById(\"cuenta-btn\");\nconst menu = document.getElementById(\"cuenta-menu\");\n\nboton.addEventListener(\"click\", () => {\n  menu.hidden = !menu.hidden;\n});"},"editable":["index.html","app.js","styles.css"],"networkLog":[],"tests":[{"name":"«Mi cuenta» es un botón que recibe el foco","type":"dom","code":"const b = $('#cuenta-btn'); if (!b) return 'Falta #cuenta-btn.'; b.focus(); const esBoton = b.tagName === 'BUTTON' || (b.getAttribute('role') === 'button' && b.tabIndex >= 0); return (esBoton && document.activeElement === b) || 'No es un botón enfocable.';"},{"name":"Anuncia si está expandido","type":"dom","code":"const b = $('#cuenta-btn'); if (b.getAttribute('aria-expanded') !== 'false') return 'Cerrado debería tener aria-expanded=\"false\".'; click('#cuenta-btn'); await wait(20); const ok = b.getAttribute('aria-expanded') === 'true'; click('#cuenta-btn'); await wait(20); return (ok && b.getAttribute('aria-expanded') === 'false') || 'aria-expanded no refleja el estado.';"},{"name":"Indica qué menú controla","type":"dom","code":"return $('#cuenta-btn').getAttribute('aria-controls') === 'cuenta-menu';"}],"regressionTests":[{"name":"El clic abre y cierra el menú","type":"dom","code":"click('#cuenta-btn'); await wait(20); const abierto = !$('#cuenta-menu').hidden; click('#cuenta-btn'); await wait(20); return abierto && $('#cuenta-menu').hidden;"},{"name":"El menú empieza cerrado","type":"dom","code":"return $('#cuenta-menu').hidden === true;"},{"name":"Mantiene sus tres opciones","type":"dom","code":"return $$('#cuenta-menu a').length === 3;"},{"name":"El botón sigue mostrando «Mi cuenta»","type":"dom","code":"return /Mi cuenta/.test(text('#cuenta-btn')) && rect('#cuenta-btn').width > 0;"}],"hints":["Un <div> con click no es enfocable ni tiene rol. ¿Qué elemento nativo ya trae foco, Enter/Espacio y rol de botón?","Añade aria-expanded (y actualízalo en el click) y aria-controls=\"cuenta-menu\"."],"solution":{"index.html":"<header class=\"barra\">\n  <span>Panel</span>\n  <button type=\"button\" class=\"cuenta\" id=\"cuenta-btn\" aria-expanded=\"false\" aria-controls=\"cuenta-menu\">Mi cuenta ▾</button>\n  <ul id=\"cuenta-menu\" class=\"cuenta-menu\" hidden>\n    <li><a href=\"#\">Perfil</a></li>\n    <li><a href=\"#\">Facturación</a></li>\n    <li><a href=\"#\">Cerrar sesión</a></li>\n  </ul>\n</header>","app.js":"const boton = document.getElementById(\"cuenta-btn\");\nconst menu = document.getElementById(\"cuenta-menu\");\n\nboton.addEventListener(\"click\", () => {\n  menu.hidden = !menu.hidden;\n  boton.setAttribute(\"aria-expanded\", String(!menu.hidden));\n});"},"rootCause":"El disparador es un <div>: no entra en el orden de tabulación, no responde a Enter/Espacio y el lector no lo anuncia como botón. Usar <button type=\"button\"> resuelve foco, teclado y rol de golpe; aria-expanded (sincronizado en el click) y aria-controls comunican el estado del menú.","suspects":[]}$webwiz_spec$::jsonb, false),
  ('inc-356', 'Los errores del formulario de registro no se anuncian', 'Solo cambia el color del borde; el lector no dice nada. Esperado: El lector anuncia el error y lo asocia al campo', 'incidencias', 'incident', 'semi_senior', ARRAY['aria-invalid', 'aria-describedby', 'regiones vivas']::TEXT[], $webwiz_spec${"id":"inc-356","number":356,"type":"incident","title":"Los errores del formulario de registro no se anuncian","area":"accesibilidad","difficulty":"semi_senior","concepts":["aria-invalid","aria-describedby","regiones vivas"],"durationMin":8,"ticket":{"reporter":"Auditoría de accesibilidad","priority":"media","device":"móvil + VoiceOver","steps":["Escribir «ana@» en Email","Pulsar «Crear cuenta»"],"expected":"El lector anuncia el error y lo asocia al campo","actual":"Solo cambia el color del borde; el lector no dice nada"},"viewport":390,"files":{"index.html":"<main>\n  <h1>Crear cuenta</h1>\n  <form id=\"registro\" novalidate>\n    <label for=\"email\">Email</label>\n    <input id=\"email\" type=\"email\">\n    <p id=\"email-error\" class=\"error\" hidden></p>\n    <button>Crear cuenta</button>\n  </form>\n  <p id=\"ok\" hidden>¡Gracias! Revisa tu correo.</p>\n</main>","styles.css":"body { margin: 0; padding: 16px; font-family: system-ui, sans-serif; }\n#email { display: block; width: 100%; min-height: 44px; margin-top: 6px; box-sizing: border-box; }\n.invalido { border: 2px solid #cf222e; }\n.error { color: #cf222e; margin: 6px 0 0; }\nbutton { min-height: 44px; margin-top: 12px; }","app.js":"const form = document.getElementById(\"registro\");\nconst email = document.getElementById(\"email\");\nconst error = document.getElementById(\"email-error\");\nconst ok = document.getElementById(\"ok\");\n\nform.addEventListener(\"submit\", (e) => {\n  e.preventDefault();\n  const valido = /^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$/.test(email.value);\n  email.classList.toggle(\"invalido\", !valido);\n  error.hidden = valido;\n  error.textContent = valido ? \"\" : \"Introduce un email válido\";\n  ok.hidden = !valido;\n});"},"editable":["index.html","app.js"],"networkLog":[],"tests":[{"name":"El campo se marca como inválido","type":"dom","code":"type('#email', 'ana@'); $('#registro').requestSubmit(); await wait(20); return $('#email').getAttribute('aria-invalid') === 'true' || 'Falta aria-invalid=\"true\" en el campo.';"},{"name":"El error está asociado al campo","type":"dom","code":"return ($('#email').getAttribute('aria-describedby') || '').split(/\\s+/).includes('email-error') || 'El campo no apunta a #email-error con aria-describedby.';"},{"name":"El error se anuncia al aparecer","type":"dom","code":"const e = $('#email-error'); const vivo = e.getAttribute('role') === 'alert' || ['assertive', 'polite'].includes(e.getAttribute('aria-live')); return vivo || 'El mensaje no está en una región viva (role=\"alert\").';"},{"name":"Al corregirlo deja de ser inválido","type":"dom","code":"type('#email', 'ana@ejemplo.com'); $('#registro').requestSubmit(); await wait(20); return $('#email').getAttribute('aria-invalid') !== 'true';"}],"regressionTests":[{"name":"Muestra el texto del error","type":"dom","code":"type('#email', 'ana@'); $('#registro').requestSubmit(); await wait(20); return !$('#email-error').hidden && text('#email-error') === 'Introduce un email válido';"},{"name":"Con un email válido se crea la cuenta","type":"dom","code":"type('#email', 'ana@ejemplo.com'); $('#registro').requestSubmit(); await wait(20); return !$('#ok').hidden && $('#email-error').hidden;"},{"name":"Mantiene el borde rojo como pista visual","type":"dom","code":"type('#email', 'x'); $('#registro').requestSubmit(); await wait(20); return $('#email').classList.contains('invalido');"}],"hints":["El color no llega al lector de pantalla. ¿Qué atributo marca un campo como inválido?","aria-describedby=\"email-error\" en el input y role=\"alert\" en el mensaje; actualiza aria-invalid al validar."],"solution":{"index.html":"<main>\n  <h1>Crear cuenta</h1>\n  <form id=\"registro\" novalidate>\n    <label for=\"email\">Email</label>\n    <input id=\"email\" type=\"email\" aria-describedby=\"email-error\">\n    <p id=\"email-error\" class=\"error\" role=\"alert\" hidden></p>\n    <button>Crear cuenta</button>\n  </form>\n  <p id=\"ok\" hidden>¡Gracias! Revisa tu correo.</p>\n</main>","app.js":"const form = document.getElementById(\"registro\");\nconst email = document.getElementById(\"email\");\nconst error = document.getElementById(\"email-error\");\nconst ok = document.getElementById(\"ok\");\n\nform.addEventListener(\"submit\", (e) => {\n  e.preventDefault();\n  const valido = /^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$/.test(email.value);\n  email.classList.toggle(\"invalido\", !valido);\n  email.setAttribute(\"aria-invalid\", String(!valido));\n  error.hidden = valido;\n  error.textContent = valido ? \"\" : \"Introduce un email válido\";\n  ok.hidden = !valido;\n});"},"rootCause":"El error solo se comunica con color y con un párrafo que aparece sin anunciarse. Falta marcar el campo con aria-invalid, asociar el mensaje con aria-describedby para que se lea al enfocar el campo y poner el mensaje en una región viva (role=\"alert\") para que se anuncie al aparecer.","suspects":[]}$webwiz_spec$::jsonb, false),
  ('inc-901', 'Un comentario ejecuta código en el navegador de los lectores', 'Un comentario con HTML se interpreta y ejecuta JavaScript (onerror). Esperado: Los comentarios se muestran como texto', 'incidencias', 'incident', 'senior', ARRAY['XSS', 'innerHTML vs textContent']::TEXT[], $webwiz_spec${"id":"inc-901","number":901,"type":"incident","title":"Un comentario ejecuta código en el navegador de los lectores","area":"seguridad","difficulty":"senior","concepts":["XSS","innerHTML vs textContent"],"durationMin":10,"ticket":{"reporter":"Equipo de seguridad","priority":"alta","device":"todos","steps":["Abrir la entrada del blog","Cargar los comentarios"],"expected":"Los comentarios se muestran como texto","actual":"Un comentario con HTML se interpreta y ejecuta JavaScript (onerror)"},"viewport":768,"files":{"index.html":"<main>\n  <h1>Comentarios</h1>\n  <ul id=\"comentarios\"></ul>\n</main>","styles.css":"body { margin: 0; padding: 24px; font-family: system-ui, sans-serif; }\n#comentarios { list-style: none; padding: 0; }\n#comentarios li { padding: 12px; border: 1px solid #d0d7de; border-radius: 8px; margin-bottom: 8px; }\n#comentarios p { margin: 4px 0 0; }","app.js":"const lista = document.getElementById(\"comentarios\");\n\nasync function cargar() {\n  const res = await fetch(\"/api/comentarios\");\n  const comentarios = await res.json();\n  lista.innerHTML = comentarios\n    .map((c) => `<li><strong>${c.autor}</strong><p>${c.texto}</p></li>`)\n    .join(\"\");\n}\n\ncargar();"},"editable":["app.js"],"networkLog":[{"method":"GET","url":"/api/comentarios","status":200,"body":[{"autor":"Ana","texto":"¡Qué buen artículo!"},{"autor":"Mallory","texto":"<img src=\"x\" onerror=\"window.__xss = 1\">Mira esto"}],"delayMs":40}],"tests":[{"name":"No se ejecuta el código del comentario","type":"dom","code":"await wait(200); return window.__xss !== 1 || 'Se ejecutó el onerror inyectado.';"},{"name":"El HTML del comentario no se interpreta","type":"dom","code":"return !$('#comentarios img') || 'Hay un <img> inyectado en la lista.';"},{"name":"El texto se muestra tal cual","type":"dom","code":"return ($$('#comentarios li')[1] || { textContent: '' }).textContent.includes('<img src=\"x\"');"}],"regressionTests":[{"name":"Se cargan los dos comentarios","type":"dom","code":"await wait(150); return $$('#comentarios li').length === 2;"},{"name":"El autor va en negrita y el texto en un párrafo","type":"dom","code":"const li = $$('#comentarios li')[0]; return !!li && li.querySelector('strong')?.textContent === 'Ana' && li.querySelector('p')?.textContent === '¡Qué buen artículo!';"},{"name":"Se piden al servidor","type":"dom","code":"return requests().some(r => r.url === '/api/comentarios');"}],"hints":["innerHTML interpreta cualquier etiqueta que venga en los datos del usuario.","Crea los elementos con createElement y asigna los datos con textContent."],"solution":{"app.js":"const lista = document.getElementById(\"comentarios\");\n\nasync function cargar() {\n  const res = await fetch(\"/api/comentarios\");\n  const comentarios = await res.json();\n  lista.replaceChildren(\n    ...comentarios.map((c) => {\n      const li = document.createElement(\"li\");\n      const autor = document.createElement(\"strong\");\n      autor.textContent = c.autor;\n      const texto = document.createElement(\"p\");\n      texto.textContent = c.texto;\n      li.append(autor, texto);\n      return li;\n    }),\n  );\n}\n\ncargar();"},"rootCause":"Los comentarios llegan del servidor con texto escrito por usuarios y se insertan con innerHTML, que interpreta las etiquetas. Un <img> con onerror ejecuta JavaScript ajeno en la página (XSS almacenado). Hay que tratar los datos como texto: createElement + textContent (o escapar el HTML).","suspects":[]}$webwiz_spec$::jsonb, false)
